<script setup lang="ts">
import { tUi } from '../i18n'

import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Plus, Refresh, Search } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { authUser } from '../auth'
import { errorText, http, normalizeService, payload, rows, serviceRequest } from '../api'
import { isMobileDraft, mobileBuildDefaults, mobileFormat, mobileMissingFields, mobileEnvironment, mobileEnvironmentError, mobileBuildError } from '../mobile'
import ServiceIdentity from '../components/ServiceIdentity.vue'
import BuildEngineSelect from '../components/BuildEngineSelect.vue'
import { buildEngineLabel } from '../buildEngine'
import type { BuildEngine, Service } from '../types'

const router=useRouter(), loading=ref(false), error=ref(''), services=ref<Service[]>([]), keyword=ref(''), draftOnly=ref(false), dialog=ref(false), saving=ref(false)
const form=reactive({name:'',code:'',gitUrl:'',defaultBranch:'master',buildEngine:'GITHUB' as BuildEngine,format:'APK' as 'APK'|'AAB'})
const drafts=computed(()=>services.value.filter(isMobileDraft).length)
const enabledCount=computed(()=>services.value.filter(enabled).length)
const filtered=computed(()=>services.value.filter(service=>(!draftOnly.value||isMobileDraft(service))&&`${service.name} ${service.code}`.toLowerCase().includes(keyword.value.trim().toLowerCase())))
function needsEnvironment(service:Service){return Boolean(mobileBuildError(service.mobileBuild))}
function enabled(service:Service){return service.status!==false&&service.status!=='DISABLED'}
function environmentEntries(service:Service){return [{name:'prod',label:tUi('生产')},{name:'test',label:tUi('预生产')},...(mobileEnvironment(service.mobileBuild,'dev')?.enabled?[{name:'dev',label:tUi('开发')}]:[])].map(environment=>{const profile=mobileEnvironment(service.mobileBuild,environment.name);const configured=Boolean(profile?.enabled&&!mobileEnvironmentError(service.mobileBuild,environment.name)&&service.mobileBuild?.flutterVersion?.trim());return{...environment,configured,status:!profile?.enabled?tUi('未启用'):configured?tUi('已配置'):tUi('待完善'),packageName:profile?.applicationId||tUi('包名尚未配置')}})}
function repositoryLabel(value?:string){return value?.replace(/^git@github\.com:/,'github.com/').replace(/^https?:\/\//,'').replace(/\.git$/,'')||tUi('尚未配置 Git 仓库')}
async function load(){loading.value=true;try{services.value=rows<Record<string,unknown>>((await http.get('/apps/services')).data).map(normalizeService).filter(service=>service.serviceType==='FLUTTER_ANDROID');error.value=''}catch(reason){error.value=errorText(reason,tUi('读取 App 列表失败'))}finally{loading.value=false}}
function open(){Object.assign(form,{name:'',code:'',gitUrl:'',defaultBranch:'master',buildEngine:'GITHUB',format:'APK'});dialog.value=true}
async function save(){if(saving.value)return;if(!form.name.trim()||!form.code.trim()||!form.gitUrl.trim())return ElMessage.warning(tUi('请填写 App 名称、标识和 Git 仓库地址'));saving.value=true;try{const result=payload<{id:number|string}>(await http.post('/apps/services',serviceRequest({name:form.name.trim(),code:form.code.trim(),gitUrl:form.gitUrl.trim(),defaultBranch:form.defaultBranch.trim()||'master',buildEngine:form.buildEngine,serviceType:'FLUTTER_ANDROID',buildTool:'Flutter',mobileBuild:{...mobileBuildDefaults(form.format),versionPolicy:authUser.value?.admin?'AUTO':'MANUAL'},status:false})),{} as {id:number});if(!result.id)throw new Error(tUi('未读取到 App 编号，请刷新列表确认登记结果'));dialog.value=false;ElMessage.success(tUi('App 已登记，完成构建配置后再启用'));await router.push(`/apps/${result.id}?tab=mobile`)}catch(reason){ElMessage.error(errorText(reason,tUi('登记 App 失败')))}finally{saving.value=false}}
onMounted(load)
</script>

<template>
  <div class="page-head"><div><h2>{{ tUi('App 发布') }}</h2><p>{{ tUi('管理应用构建、安装包与各环境的交付。') }}</p></div><el-button type="primary" :icon="Plus" @click="open">{{ tUi('登记 App') }}</el-button></div>
  <section class="panel apps-workspace" v-loading="loading">
    <div class="app-catalog-summary"><div><strong>{{ tUi('应用目录') }}</strong><span>{{ tUi('{0} 个应用', services.length) }}</span><span>{{ tUi('{0} 个已启用', enabledCount) }}</span></div><span v-if="drafts" class="app-draft-count">{{ tUi('{0} 个待配置', drafts) }}</span></div>
    <div class="panel-title apps-toolbar"><div class="actions"><el-input v-model="keyword" :prefix-icon="Search" clearable :placeholder="tUi('搜索 App 名称或标识')" :aria-label="tUi('搜索 App')"/><el-checkbox v-model="draftOnly">{{ tUi('只看待配置（{0}）', drafts) }}</el-checkbox></div><el-button text :icon="Refresh" :loading="loading" @click="load">{{ tUi('刷新') }}</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
    <div v-else-if="loading&&!services.length" class="app-initial-loading" role="status"><el-skeleton :rows="5" animated/><p>{{ tUi('正在读取应用与环境配置…') }}</p></div>
    <div v-else-if="!filtered.length" class="empty"><div><strong>{{services.length?tUi('没有匹配的 App'):tUi('还没有登记 App')}}</strong><p>{{services.length?tUi('调整搜索或取消待配置筛选。'):tUi('先登记名称和代码仓库，再补充 Flutter 与签名配置。')}}</p><el-button v-if="!services.length" type="primary" @click="open">{{ tUi('登记第一个 App') }}</el-button></div></div>
    <article v-for="service in filtered" :key="service.id" class="app-row">
      <div class="app-row-head"><ServiceIdentity :service="service" large/><el-tag :type="isMobileDraft(service)||enabled(service)&&needsEnvironment(service)?'warning':enabled(service)?'success':'info'" effect="plain">{{isMobileDraft(service)?tUi('待配置（未启用）'):enabled(service)?needsEnvironment(service)?tUi('需完善环境配置'):tUi('已启用'):tUi('已停用')}}</el-tag></div>
      <div class="app-row-body"><div class="app-build-overview"><p class="app-repository" :title="service.gitUrl">{{repositoryLabel(service.gitUrl)}}</p><dl class="app-facts"><div><dt>{{ tUi('构建方式') }}</dt><dd>{{buildEngineLabel(service.buildEngine)}}</dd></div><div><dt>{{ tUi('安装包') }}</dt><dd>{{mobileFormat(service.mobileBuild)==='APK'?tUi('完整 APK'):'AAB'}}</dd></div><div><dt>Flutter</dt><dd>{{service.mobileBuild?.flutterVersion||tUi('待配置')}}</dd></div><div class="app-default-branch"><dt>{{ tUi('默认分支') }}</dt><dd :title="service.defaultBranch">{{service.defaultBranch||'master'}}</dd></div></dl></div><div class="app-environments" :aria-label="tUi('构建环境配置')"><div v-for="environment in environmentEntries(service)" :key="environment.name" class="app-environment"><div><b>{{environment.label}}</b><span :class="{configured:environment.configured,incomplete:environment.status===tUi('待完善')}"><i></i>{{environment.status}}</span></div><p :title="environment.packageName">{{environment.packageName}}</p></div></div></div>
      <div v-if="isMobileDraft(service)||enabled(service)&&needsEnvironment(service)" class="app-setup-note"><b>{{ tUi('继续完成配置') }}</b><span>{{mobileMissingFields(service.mobileBuild).length?tUi('待补充：')+mobileMissingFields(service.mobileBuild).join('、'):tUi('请检查构建配置中的格式、版本和签名信息')}}</span></div>
      <div class="app-row-foot"><span>{{enabled(service)?tUi('构建时选择环境，安装包按相同环境交付。'):tUi('配置完成并启用后，即可构建安装包。')}}</span><div><el-button @click="router.push(`/apps/${service.id}?tab=artifacts`)">{{ tUi('安装包与记录') }}</el-button><el-button @click="router.push(`/apps/${service.id}?tab=mobile`)">{{isMobileDraft(service)?tUi('继续配置'):tUi('应用配置')}}</el-button><el-button type="primary" :disabled="!enabled(service)||needsEnvironment(service)" @click="router.push(`/apps/${service.id}/build`)">{{ tUi('新建构建') }}</el-button></div></div>
    </article>
  </section>
  <el-dialog v-model="dialog" :title="tUi('登记 App')" width="600px" :close-on-click-modal="false"><p class="app-register-note">{{ tUi('先登记仓库，保存为未启用的草稿。Flutter 版本、包名和签名信息稍后配置。') }}</p><el-form label-position="top" :disabled="saving"><el-form-item :label="tUi('App 名称')" required><el-input v-model="form.name" :placeholder="tUi('例如：示例移动应用')"/></el-form-item><el-form-item :label="tUi('App 标识')" required><el-input v-model="form.code" :placeholder="tUi('例如：sample-mobile-app')"/></el-form-item><el-form-item :label="tUi('Git 仓库地址')" required><el-input v-model="form.gitUrl" placeholder="git@github.com:team/app.git"/></el-form-item><el-form-item :label="tUi('默认分支')"><el-input v-model="form.defaultBranch"/></el-form-item><BuildEngineSelect v-model="form.buildEngine" :disabled="saving"/><el-form-item :label="tUi('安装包格式')"><el-radio-group v-model="form.format"><el-radio-button value="APK">{{ tUi('完整 APK · 内部升级') }}</el-radio-button><el-radio-button value="AAB">{{ tUi('AAB · 商店分发') }}</el-radio-button></el-radio-group></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="dialog=false">{{ tUi('取消') }}</el-button><el-button type="primary" :loading="saving" @click="save">{{ tUi('保存为待配置 App') }}</el-button></template></el-dialog>
</template>

<style scoped>
.apps-workspace{padding-top:0}.app-catalog-summary{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:19px 0;border-bottom:1px solid #dce3ec;margin-bottom:20px}.app-catalog-summary>div{display:flex;align-items:baseline;gap:18px}.app-catalog-summary strong{color:#203149;font-size:14px;font-weight:650}.app-catalog-summary span{font-size:12px;color:#607087}.app-catalog-summary .app-draft-count{color:#b37519}.apps-toolbar .actions{gap:18px}.apps-toolbar .el-input{width:280px}.apps-toolbar{margin-bottom:18px}.app-row{padding:24px 0;border-top:1px solid #dce3ec}.app-row:last-child{padding-bottom:0}.app-row-head{display:flex;align-items:center;justify-content:space-between;gap:18px}.app-row-head :deep(.service-identity--large .service-identity__name){font-size:22px;color:#203149}.app-row-head>.el-tag{flex-shrink:0}.app-row-body{display:grid;grid-template-columns:minmax(0,1fr) minmax(260px,.68fr);gap:26px;margin-top:18px}.app-build-overview{min-width:0}.app-repository{font-size:12px;color:#607087;margin:0 0 18px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.app-facts{display:grid;grid-template-columns:minmax(140px,1.25fr) minmax(70px,.8fr) minmax(80px,.8fr);gap:14px 20px;margin:0}.app-facts>div{min-width:0}.app-facts dt{font-size:11px;color:#607087;margin:0 0 6px}.app-facts dd{font-size:13px;color:#203149;font-weight:550;margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.app-default-branch{grid-column:1/-1;display:flex;align-items:baseline;gap:14px;padding-top:2px}.app-default-branch dt{flex-shrink:0;margin:0}.app-default-branch dd{font-size:12px}.app-environments{border-left:1px solid #e3e9f0;padding-left:26px;min-width:0;display:flex;flex-direction:column;justify-content:center}.app-environment+.app-environment{border-top:1px solid #e9edf3;margin-top:11px;padding-top:11px}.app-environment>div{display:flex;justify-content:space-between;align-items:center;gap:10px}.app-environment b{font-size:12px;color:#203149;font-weight:600}.app-environment span{display:inline-flex;align-items:center;gap:6px;font-size:11px;color:#607087}.app-environment i{width:5px;height:5px;border-radius:50%;background:#a3adba}.app-environment .configured{color:#168269}.app-environment .configured i{background:#168269}.app-environment .incomplete{color:#b37519}.app-environment .incomplete i{background:#b37519}.app-environment p{font-size:11px;color:#607087;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:7px 0 0}.app-setup-note{display:flex;gap:14px;align-items:baseline;margin:18px 0 0;padding:10px 13px;background:#fff8e9;border-left:3px solid #d6aa57;color:#8e641e;font-size:12px;line-height:1.8}.app-setup-note b{font-weight:600;flex-shrink:0}.app-row-foot{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-top:20px;padding-top:16px;border-top:1px solid #edf0f5}.app-row-foot>span{color:#607087;font-size:12px;line-height:1.7;max-width:420px}.app-row-foot>div{display:flex;gap:9px;flex-shrink:0}.app-row-foot .el-button+.el-button{margin-left:0}.app-register-note{margin:0 0 22px;font-size:13px;color:#607087;line-height:1.8}.app-initial-loading{padding:12px 0}.app-initial-loading p{font-size:13px;color:#607087;margin-top:20px}
@media(max-width:1100px){.app-row-foot{align-items:flex-start;flex-direction:column}.app-row-body{grid-template-columns:minmax(0,1fr) minmax(220px,.7fr);gap:20px}.app-environments{padding-left:20px}.app-facts{grid-template-columns:minmax(125px,1.2fr) minmax(65px,.8fr) minmax(65px,.8fr);gap:12px}}
@media(max-width:750px){.app-row-body{grid-template-columns:1fr}.app-environments{border-left:0;padding:15px 0 0;border-top:1px solid #e3e9f0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.app-environment+.app-environment{border:0;margin:0;padding:0}.app-catalog-summary>div{gap:12px}.app-catalog-summary>div>span:last-child{display:none}}
@media(max-width:650px){.apps-toolbar>.actions{width:100%;flex-wrap:wrap;gap:8px}.apps-toolbar .el-input{width:100%}.apps-toolbar{flex-wrap:wrap}.app-row-head{align-items:flex-start;gap:8px;flex-wrap:wrap}.app-row-head :deep(.service-identity){flex:1;min-width:200px}.app-row-head :deep(.service-identity__name){font-size:18px!important;white-space:normal;overflow-wrap:anywhere}.app-row-head>.el-tag{margin-left:59px}.app-setup-note{flex-direction:column;gap:4px}.app-row-foot>div{width:100%;flex-wrap:wrap}.app-row-foot .el-button{flex:1;font-size:12px;padding-left:10px;padding-right:10px}.app-facts{grid-template-columns:1.3fr .8fr .8fr;gap:12px}.app-facts dd{font-size:12px}.app-catalog-summary span{font-size:11px}.app-environment>div{gap:5px}}
</style>
